const kurmaliVocab=[{english:"Hello / Greetings",kurmali:"Johar",script:"जोहार",pronunciation:"Johar"},{english:"Water",kurmali:"Pani",script:"पानी",pronunciation:"Pani"},{english:"Mother",kurmali:"Maio",script:"माइयो",pronunciation:"Ma-i-yo"},{english:"Father",kurmali:"Bapa",script:"बापा",pronunciation:"Baapa"},{english:"House",kurmali:"Ghar",script:"घर",pronunciation:"Ghar"},{english:"Food / Rice",kurmali:"Bhat",script:"भात",pronunciation:"Bhaat"},{english:"How are you?",kurmali:"Keson aaha?",script:"केसन आहा?",pronunciation:"Keson aaha?"},{english:"I am fine.",kurmali:"Moi bhal achi.",script:"मोइ भाल अछि।",pronunciation:"Moi bhal achi."}];document.addEventListener("DOMContentLoaded",()=>{const i=document.getElementById("vocab-grid");let n=window.speechSynthesis;kurmaliVocab.forEach((a,e)=>{const t=document.createElement("div");t.className="vocab-card",t.innerHTML=`\n            <div class="card-inner">\n                \x3c!-- Front of Card --\x3e\n                <div class="card-front">\n                    <div class="word-english">${a.english}</div>\n                    <div class="click-hint">Click to flip</div>\n                </div>\n                \x3c!-- Back of Card --\x3e\n                <div class="card-back">\n                    <div class="word-kurmali">${a.kurmali}</div>\n                    <div class="word-script">${a.script}</div>\n                    <button class="audio-btn" data-speak="${a.pronunciation}" aria-label="Listen to pronunciation">🔊</button>\n                </div>\n            </div>\n        `,t.addEventListener("click",i=>{i.target.closest(".audio-btn")||t.classList.toggle("is-flipped")});const c=t.querySelector(".audio-btn");c.addEventListener("click",i=>{i.stopPropagation();const a=c.getAttribute("data-speak");n.speaking&&n.cancel();const e=new SpeechSynthesisUtterance(a),t=n.getVoices().find(i=>i.lang.includes("hi-IN")||i.lang.includes("hi"));t&&(e.voice=t),e.rate=.9,n.speak(e)}),i.appendChild(t)})});